/// <summary>
/// Notification varliginin veritabani (Entity Framework Core) yapilandirmasini tanimlar.
/// </summary>
public class NotificationConfiguration : IEntityTypeConfiguration<Notification>
{
    /// <summary>
    /// Notification varligi icin tablo adi, birincil anahtar, alan kisitlari ve iliskileri yapilandirir.
    /// </summary>
    public void Configure(EntityTypeBuilder<Notification> builder)
    {
        // Tablo adini belirtir.
        builder.ToTable("Notification", "notification");

        // Birincil anahtari tanimlar.
        builder.HasKey(x => x.Id);

        // Bildirimin turu.
        builder.Property(x => x.Type)
