            .HasMaxLength(50);

        // Bildirimin basligi.
        builder.Property(x => x.Title)
            .IsRequired(true)
            .HasMaxLength(200);

        // Bildirimin icerik metni.
        builder.Property(x => x.Body)
            .IsRequired(true)
            .HasMaxLength(300);

        // Bildirime ait ek verilerin JSON formatinda tutuldugu alan.
        builder.Property(x => x.DataJson)
            .IsRequired(false)
            .HasMaxLength(2000);

        // Bildirimde gosterilen gorselin adresi.
        builder.Property(x => x.ImageUrl)
            .IsRequired(false)
            .HasMaxLength(500);

        // Iliskiler (foreign key) yapilandirmasi.
        // Bildirimin gonderildigi kullanicinin kimligi.
        builder.HasOne<ApplicationUser>()
